 root.querySelectorAll('[data-receipt-shopping]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const index=Number(form.dataset.receiptShopping),item=receipt.items.find(i=>i.item_index===index),selected=item.matches.find(m=>m.id===Number(form.elements.shopping.value));if(!selected||!form.elements.purchased.checked){say('購入した買い物と必要数量を確認してください。',true);return;}action(async()=>{await api({action:'receipt_shopping_confirm',id:receipt.id,item_index:index,shopping:selected,purchase_confirmed:true});await receiptDetail(receipt.id);say('選んだ買い物を購入済みにしました。');});});
