 const date=url.searchParams.get('date')||boot.today,stored=itemFor(date),item=stored?{...stored,recipe:{...stored.recipe,name:[stored.recipe.name,...(stored.sides||[]).map(r=>r.name)].join(' + '),steps:stored.sides?.length?[stored.recipe,...stored.sides].flatMap(r=>r.steps.map(step=>r.name+' · '+step)):stored.recipe.steps}}:null;if(!item){paint('<section class="card"><p>この日の献立は未登録です。</p><a href="/app/meals.php?view=week">今週の献立を決める</a></section>');return;}
